</TR>
<TR>
	<TD class="tr1 td0"><SPAN class="p1 ft1">inrättande av en internationell</SPAN> </TD>
	<TD class="tr1 td1"><SPAN class="p2 ft1">2025/26:232</SPAN> </TD>
</TR>
<TR>
	<TD class="tr2 td2"><SPAN class="p1 ft1">skadeståndskommission för Ukraina</SPAN> </TD>
	<TD class="tr2 td3"><SPAN class="p3 ft2">&nbsp;</SPAN> </TD>
